from datetime import datetime, timedelta, timezone
from azure.identity import DefaultAzureCredential
from azure.monitor.query import MetricsQueryClient, MetricAggregationType


def aggregate_metric_stats(payload, config=None):
    config = config or {}
    start = datetime.fromtimestamp(payload['start_time'], tz=timezone.utc)
    end = datetime.fromtimestamp(payload['end_time'], tz=timezone.utc)
    with DefaultAzureCredential() as credential:
        with MetricsQueryClient(credential) as client:
            result = client.query_resource(config['resource_id'], metric_names=[payload['metric']],
                timespan=(start, end), granularity=timedelta(seconds=config.get('period_seconds', 60)),
                aggregations=[MetricAggregationType.AVERAGE, MetricAggregationType.MIN, MetricAggregationType.MAX, MetricAggregationType.TOTAL])
    stats = {'average': None, 'min': None, 'max': None, 'total': None}
    for metric in result.metrics:
        for series in metric.timeseries:
            for point in series.data:
                if point.average is not None:
                    stats['average'] = float(point.average)
                if point.minimum is not None:
                    stats['min'] = float(point.minimum)
                if point.maximum is not None:
                    stats['max'] = float(point.maximum)
                if point.total is not None:
                    stats['total'] = float(point.total)
    return stats

from typing import Dict, List


def normalize_metric_payload(payload: Dict) -> Dict:
    normalized = {
        'start_time': payload.get('start_time', None),
        'end_time': payload.get('end_time', None),
        'metric': payload.get('metric', None),
        'filter': payload.get('filter', None),
        'filter1': payload.get('filter1', None),
        'filter2': payload.get('filter2', None)
    }
    return {k: v for k, v in normalized.items() if v is not None}


def parse_metric_response(response: Dict) -> Dict:
    points = [{'timestamp': point['timestamp'], 'value': point['value']} for point in response.get('points', []) if point['value'] is not None]
    return {'points': sorted(points, key=lambda point: point['timestamp'])}


def parse_metric_comparison_response(response: Dict) -> Dict:
    series1 = [{'timestamp': point['timestamp'], 'value': point['value']} for point in response.get('series1', []) if point['value'] is not None]
    series2 = [{'timestamp': point['timestamp'], 'value': point['value']} for point in response.get('series2', []) if point['value'] is not None]
    return {'series1': sorted(series1, key=lambda point: point['timestamp']), 'series2': sorted(series2, key=lambda point: point['timestamp'])}

from datetime import datetime, timedelta, timezone
from azure.identity import DefaultAzureCredential
from azure.monitor.query import MetricsQueryClient, MetricAggregationType


def summarize_metric_trends(payload, config=None):
    config = config or {}
    start = datetime.fromtimestamp(payload['start_time'], tz=timezone.utc)
    end = datetime.fromtimestamp(payload['end_time'], tz=timezone.utc)
    with DefaultAzureCredential() as credential:
        with MetricsQueryClient(credential) as client:
            result = client.query_resource(config['resource_id'], metric_names=[payload['metric']],
                timespan=(start, end), granularity=timedelta(seconds=config.get('period_seconds', 60)),
                aggregations=[MetricAggregationType.AVERAGE])
    points = [{'timestamp': point.timestamp.timestamp(), 'value': float(point.average)}
              for metric in result.metrics for series in metric.timeseries
              for point in series.data if point.average is not None]
    if len(points) < 2:
        return {'trend': 'insufficient data'}
    last_point = points[-1]
    second_last_point = points[-2]
    if last_point['value'] > second_last_point['value']:
        return {'trend': 'increasing'}
    elif last_point['value'] < second_last_point['value']:
        return {'trend': 'decreasing'}
    else:
        return {'trend': 'stable'}

import re


def check_metric_annotation_safety(annotation):
    unsafe_patterns = [r'\b(password|secret|token)\b', r'\b(sql|exec|drop|delete)\b']
    for pattern in unsafe_patterns:
        if re.search(pattern, annotation, re.IGNORECASE):
            return False
    return True
